// Simple Asteroid Dodge game based on IDEA.md
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth || 800;
  const height = canvas.height = canvas.offsetHeight || 600;

  // Ship definition
  const ship = {
    w: 60,
    h: 20,
    x: width / 2 - 30,
    y: height - 30,
    speed: 5,
    color: '#00f'
  };

  // Laser (single bullet at a time)
  const laser = {
    active: false,
    x: 0,
    y: 0,
    w: 4,
    h: 12,
    speed: 8,
    color: '#f00'
  };

  // Asteroid collection
  const asteroids = [];
  const asteroidSpawnInterval = 1500; // ms
  let lastSpawn = 0;
  const asteroidSpeedBase = 1.5;
  const asteroidSpeedIncrement = 0.0005; // per ms

  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; if (e.code === 'Space') fireLaser(); });
  window.addEventListener('keyup', e => { keys[e.code] = false; });

  function fireLaser() {
    if (!laser.active) {
      laser.active = true;
      laser.x = ship.x + ship.w / 2 - laser.w / 2;
      laser.y = ship.y;
    }
  }

  function spawnAsteroid() {
    const radius = Math.random() * 20 + 10;
    const x = Math.random() * (width - radius * 2) + radius;
    asteroids.push({ x, y: -radius, r: radius, speed: asteroidSpeedBase + Math.random() * 1.5 });
  }

  function update(delta) {
    if (gameOver) return;
    // Move ship
    if (keys['ArrowLeft'] || keys['KeyA']) ship.x -= ship.speed;
    if (keys['ArrowRight'] || keys['KeyD']) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // Update laser
    if (laser.active) {
      laser.y -= laser.speed;
      if (laser.y + laser.h < 0) laser.active = false;
    }

    // Spawn asteroids over time
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed + asteroidSpeedIncrement * performance.now();
      // Collision with ship
      if (
        a.x + a.r > ship.x &&
        a.x - a.r < ship.x + ship.w &&
        a.y + a.r > ship.y &&
        a.y - a.r < ship.y + ship.h
      ) {
        gameOver = true;
      }
      // Collision with laser
      if (laser.active) {
        const lx = laser.x + laser.w / 2;
        const ly = laser.y;
        const dist = Math.hypot(lx - a.x, ly - a.y);
        if (dist < a.r) {
          asteroids.splice(i, 1);
          laser.active = false;
          score += 10;
          continue;
        }
      }
      // Remove if off screen
      if (a.y - a.r > height) {
        gameOver = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Laser
    if (laser.active) {
      ctx.fillStyle = laser.color;
      ctx.fillRect(laser.x, laser.y, laser.w, laser.h);
    }
    // Asteroids
    ctx.fillStyle = '#555';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    update(delta);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
